<?php require_once __DIR__ . '/lib/functions.php'; if (current_user()) redirect('dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$u=trim($_POST['userid']??'');$p=(string)($_POST['password']??'');$st=db()->prepare("SELECT account_id,userid,user_pass,sex,email,group_id,state,lastlogin FROM login WHERE userid=? AND sex<>'S' LIMIT 1");$st->execute([$u]);$row=$st->fetch(); if($row && hash_equals((string)$row['user_pass'],$p) && (int)$row['state']===0){unset($row['user_pass']);session_regenerate_id(true);$_SESSION['user']=$row;redirect('dashboard.php');} $error='Game ID หรือ Password ไม่ถูกต้อง';} require __DIR__.'/partials/header.php'; ?>
<section class="auth-wrap"><form class="auth-card compact" method="post"><span class="eyebrow">MEMBER LOGIN</span><h1>เข้าสู่ระบบ</h1><p>เข้าสู่ระบบด้วย Game ID ของคุณ</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Game ID<input name="userid" required autofocus></label><label>Password<input type="password" name="password" required></label><button class="btn primary wide">เข้าสู่ระบบ</button><small>ยังไม่มีบัญชี? <a href="register.php">สมัครสมาชิก</a></small></form></section>
